function controller(id,max,get,set){let timer=null;const host=$('#'+id+'-controls'),b=k=>host.querySelector('[data-action="'+k+'"]'),live=$('#mt-'+id+'-log');function update(){const active=timer!==null;b('play').textContent=active?'Ⅱ':get()===max()?'↻':'▶';b('play').setAttribute('aria-label',active?'暂停':get()===max()?'重新播放':'播放');b('play').setAttribute('aria-pressed',String(active));b('prev').disabled=get()===0;b('next').disabled=get()===max();live.setAttribute('aria-live',active?'off':'polite');}function pause(freeze=true){clearInterval(timer);timer=null;if(freeze)motion.pause(id);update();}function seek(n){pauseAll();set(Math.max(0,Math.min(max(),n)));update();}function play(){pauseAll();if(get()===max())set(0);motion.resume(id,Number(b('speed').value));timer=setInterval(()=>{set(Math.min(max(),get()+1));if(get()===max())pause(false);update();},Number(b('speed').value));update();}b('play').addEventListener('click',()=>timer===null?play():pause());b('prev').addEventListener('click',()=>seek(get()-1));b('next').addEventListener('click',()=>seek(get()+1));b('reset').addEventListener('click',()=>seek(0));b('speed').addEventListener('change',()=>{if(timer!==null)play();});const c={pause,seek,update};controllers.push(c);return c;}
