 txt('#mt-multi-composition',`1 页目录 + ${t.leaves} 页下级表`);$('#mt-multi-bytes').innerHTML=`${t.multiBytes.toLocaleString('en-US')} <small>B</small>`;
 txt('#mt-branch-caption',selected.allocated?`目录项 ${group} → 管理页 ${selected.start}–${selected.end}`:`目录项 ${group} 无效，对应下级表未分配`);
